from pysat.solvers import Glucose3
from pysat.card import *

n = 12
target_degree = 3
fixed_edges = [(0, 9), (1, 10), (2, 9)]

# Create variable mapping for each possible edge
edge_vars = {}
var_to_edge = {}
var_idx = 1

for u in range(n):
    for v in range(u+1, n):
        if (u, v) not in fixed_edges:
            edge_vars[(u, v)] = var_idx
            var_to_edge[var_idx] = (u, v)
            var_idx += 1

print(f"Number of variables: {var_idx - 1}")

solver = Glucose3()

# For each vertex, exactly target_degree edges must be incident to it
for v in range(n):
    # Find all edges incident to v
    incident_edges = []
    for u in range(v):
        if (u, v) in fixed_edges:
            incident_edges.append(1)  # Fixed edge, always present
        elif (u, v) in edge_vars:
            incident_edges.append(edge_vars[(u, v)])
    for w in range(v+1, n):
        if (v, w) in fixed_edges:
            incident_edges.append(1)  # Fixed edge, always present
        elif (v, w) in edge_vars:
            incident_edges.append(edge_vars[(v, w)])

    # Count how many fixed edges are incident
    fixed_count = sum(1 for e in incident_edges if e == 1)
    # Get variable edges
    var_edges = [e for e in incident_edges if e != 1]

    # We need exactly (target_degree - fixed_count) of the variable edges to be true
    needed = target_degree - fixed_count

    if needed < 0:
        print(f"UNSATISFIABLE: vertex {v} already has {fixed_count} fixed edges")
        exit()

    if needed == 0:
        # All variable edges must be false
        for e in var_edges:
            solver.add_clause([-e])
    elif needed == len(var_edges):
        # All variable edges must be true
        for e in var_edges:
            solver.add_clause([e])
    else:
        # Exactly 'needed' of the variable edges must be true
        # Use cardinality constraint
        enc = CardEnc.equals(lits=var_edges, bound=needed, encoding=EncType.pairwise)
        for clause in enc.clauses:
            solver.add_clause(clause)

if solver.solve():
    model = solver.get_model()
    edges = list(fixed_edges)
    for lit in model:
        if lit > 0 and lit in var_to_edge:
            edges.append(var_to_edge[lit])

    # Sort edges
    edges.sort()
    print("Solution found!")
    print(f"Number of edges: {len(edges)}")
    print("Edges:", edges)

    # Verify
    degree = [0] * n
    for u, v in edges:
        degree[u] += 1
        degree[v] += 1
    print("Degrees:", degree)
    assert all(d == 3 for d in degree), "Degree constraint violated!"
else:
    print("UNSATISFIABLE")

